def task_func(process_name: str) -> int:
    """
    Stops all running processes with a specific name.

    Parameters:
    process_name (str):
    pids = []
        for proc in os.popen('ps -ef').readlines():
            if process_name in proc:
                pids.append(int(proc.split()[1]))
        for pid in pids:
            try:
                os.kill(pid, signal.SIGTERM)
                time.sleep(1)
            except OSError:
                pass
        return len(pids)

