def task_func(path, delimiter="/"):
    if not path:
            raise ValueError("Path cannot be empty.")

        if not isinstance(path, str):
            raise ValueError("Path must be a string.")

        if not path:
            raise ValueError("Path cannot be empty.")

        if not os.path.exists(path):
            raise FileNotFoundError("Path does not exist.")

        components = path.split(delimiter)
        if len(components) == 1:
            return [(path, {'total': os.path.getsize(path), 'used': 0, 'free': 0})]

        disk_usage = {}
        for component in components:
            if not component:
                raise ValueError("Invalid path component.")

            if not os.path.exists(component):
                raise FileNotFoundError(f"Path component '{component}' does not exist.")

            disk_usage[component] = {'total': os.path.getsize(component), 'used': 0, 'free': 0}

        return [(component, disk_usage[component]) for component in components]
